// SMA ribbon: six simple moving averages from fast to slow.
const lengths = [10, 20, 30, 40, 50, 60];
for (const n of lengths) {
  plot("sma" + n, ta.sma(close, n), { title: "SMA " + n, style: "line" });
}
log("Ribbon over", bars.length, "bars; last close", close[close.length - 1]);

// Custom RSI with divergence markers.
// A swing low/high is confirmed `look` bars after it happens, so markers are for review only.
const len = 14;
const look = 5;
const r = ta.rsi(close, len);
plot("rsi", r, { title: "RSI " + len, pane: "separate" });

const bull = new Array(bars.length).fill(null);
const bear = new Array(bars.length).fill(null);
let lastLow = null;
let lastHigh = null;
for (let i = look; i < bars.length - look; i++) {
  if (r[i] === null) continue;
  let isLow = true;
  let isHigh = true;
  for (let k = i - look; k <= i + look; k++) {
    if (low[k] < low[i]) isLow = false;
    if (high[k] > high[i]) isHigh = false;
  }
  if (isLow) {
    // Price makes a lower low while RSI makes a higher low: bullish divergence.
    if (lastLow && low[i] < low[lastLow.i] && r[i] > lastLow.r) bull[i] = r[i];
    lastLow = { i, r: r[i] };
  }
  if (isHigh) {
    // Price makes a higher high while RSI makes a lower high: bearish divergence.
    if (lastHigh && high[i] > high[lastHigh.i] && r[i] < lastHigh.r) bear[i] = r[i];
    lastHigh = { i, r: r[i] };
  }
}
plot("bullDiv", bull, { title: "Bullish divergence", style: "dots", pane: "separate" });
plot("bearDiv", bear, { title: "Bearish divergence", style: "dots", pane: "separate" });
log(bull.filter((v) => v !== null).length, "bullish /", bear.filter((v) => v !== null).length, "bearish divergences");

// Breakout strategy: go long when the close breaks above the highest high of the previous
// 20 bars; exit when it closes below the lowest low of the previous 10 bars.
// signal(i, ...) on bar i is filled at the open of bar i + 1 by the backtester.
const entryLen = 20;
const exitLen = 10;
const upper = ta.highest(high, entryLen);
const lower = ta.lowest(low, exitLen);
plot("upper", upper, { title: "Highest " + entryLen });
plot("lower", lower, { title: "Lowest " + exitLen });

let long = false;
for (let i = 1; i < bars.length; i++) {
  const hi = upper[i - 1];
  const lo = lower[i - 1];
  if (!long && hi !== null && close[i] > hi) {
    signal(i, "enter-long");
    long = true;
  } else if (long && lo !== null && close[i] < lo) {
    signal(i, "exit");
    long = false;
  }
}
